  "Build report": function ($, $input, Date, $getWorkflowStaticData) {
// Build report: last-24h activity and pipeline health.
const rows = $input.all().map((r) => r.json).filter((r) => r.lead_id);
const now = Date.now(), day = 864e5;
const within = (d) => d && !isNaN(Date.parse(d)) && now - Date.parse(d) <= day;
const newLeads = rows.filter((r) => within(r.created_at));
const count = (arr, k) => arr.reduce((m, r) => { const v = r[k] || 'unknown'; m[v] = (m[v] || 0) + 1; return m; }, {});
const bySource = count(newLeads, 'source');
const byTier = count(newLeads, 'tier');
const replies = rows.filter((r) => within(r.replied_at)).length;
const booked = rows.filter((r) => r.status === 'booked' && within(r.updated_at)).length;
const overdue = rows.filter((r) => r.next_followup_at && Date.parse(r.next_followup_at) < now - 2 * 3600e3 && !['replied', 'booked', 'won', 'lost', 'spam', 'unsubscribed', 'nurture'].includes(r.status) && !r.owner).length;
const hotWaiting = rows.filter((r) => r.tier === 'A' && !r.owner && !['booked', 'won', 'lost'].includes(r.status));
const pipe = count(rows, 'status');
const fmt = (o) => Object.entries(o).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k}: ${v}`).join(' · ') || 'none';
const date = new Date().toISOString().slice(0, 10);
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const hotList = hotWaiting.slice(0, 10).map((r) => `<li><b>${esc(r.name || r.email)}</b> ${esc(r.company || '')}, score ${r.score}, ${esc(r.need_summary || '')}</li>`).join('');
const html = `<h2>Lead report · ${date}</h2>
<table cellpadding="6" style="border-collapse:collapse;font-family:Arial">
<tr><td><b>New leads (24h)</b></td><td>${newLeads.length}</td></tr>
<tr><td><b>By source</b></td><td>${esc(fmt(bySource))}</td></tr>
<tr><td><b>By tier</b></td><td>${esc(fmt(byTier))}</td></tr>
<tr><td><b>Replies (24h)</b></td><td>${replies}</td></tr>
<tr><td><b>Booked (24h)</b></td><td>${booked}</td></tr>
<tr><td><b>Overdue follow-ups</b></td><td>${overdue}</td></tr>
<tr><td><b>Whole pipeline</b></td><td>${esc(fmt(pipe))}</td></tr></table>
<h3>🔥 A-tier leads with no owner yet (${hotWaiting.length})</h3><ul>${hotList || '<li>None. Nice!</li>'}</ul>`;
const text = `*Lead report · ${date}*\nNew (24h): *${newLeads.length}* (${fmt(byTier)})\nBy source: ${fmt(bySource)}\nReplies: ${replies} · Booked: ${booked} · Overdue follow-ups: ${overdue}\n🔥 A-tier with no owner: *${hotWaiting.length}*`;
return [{ json: { subject: `Lead report ${date}: ${newLeads.length} new, ${hotWaiting.length} hot waiting`, html, slack_payload: { text }, stats: { new: newLeads.length, bySource, byTier, replies, booked, overdue, hotWaiting: hotWaiting.length, pipeline: pipe } } }];
  },
